-- | The solve half: materialise the stub project from @packages.json@, let
-- cabal pick versions into @cabal.project.freeze@, and have it download every
-- sdist so @generate@ never touches the network.
module Hackage2Buck.Solve
  ( solve
  , hermeticGhc
  ) where

import Data.ByteString.Lazy.Char8 qualified as BL
import Data.List (sort)
import Data.Map.Strict qualified as Map
import Data.Set qualified as Set
import Distribution.Pretty (prettyShow)
import Distribution.Types.PackageName (unPackageName)
import Distribution.Types.Version (Version)
import Hackage2Buck.Boot
import Hackage2Buck.Packages
import Hackage2Buck.Platforms
import System.Directory (createDirectoryIfMissing, listDirectory)
import System.FilePath ((</>))
import System.Process.Typed (proc, readProcessStdout_, runProcess_, setWorkingDir)

-- | The existing freeze file constrains the solve, so it acts as a lock:
-- delete it to re-solve from scratch.
solve :: Boot -> Plat -> Packages -> FilePath -> FilePath -> IO ()
solve boot host pkgs stubDir ghc = do
  createDirectoryIfMissing True stubDir
  writeFile (stubDir </> "stub.cabal") (stubCabal pkgs)
  writeFile (stubDir </> "cabal.project") (stubProject boot host)
  let cabal args = runProcess_ (setWorkingDir stubDir (proc "cabal" (args <> ["-w", ghc])))
  cabal ["freeze"]
  cabal ["build", "--only-download"]

stubCabal :: Packages -> String
stubCabal pkgs =
  unlines $
    [ "cabal-version: 3.0"
    , "-- @generated by hackage2buck solve from ../packages.json"
    , "name: stub"
    , "version: 0"
    , ""
    , "library"
    , "  build-depends:"
    ]
      <> ["    , " <> unPackageName p | p <- Set.toList (requested pkgs)]

-- | Every boot package is pinned to the installed instance: the BUCK file maps
-- them onto the toolchain's, so cabal must not pick a Hackage one instead.
stubProject :: Boot -> Plat -> String
stubProject boot host =
  unlines $
    [ "-- @generated by hackage2buck solve; overrides go in cabal.project.local"
    , "packages: ."
    , ""
    , "constraints:"
    ]
      <> ["  , " <> unPackageName p <> " installed" | p <- sort (Map.keys hostBoot)]
  where
    hostBoot = Map.findWithDefault mempty host (bootPackages boot)

-- | The toolchain's own @ghc-<version>@ binary for the host, which runs from
-- the unpacked bindist as-is. Run from the repo root.
hermeticGhc :: FilePath -> Plat -> Version -> IO FilePath
hermeticGhc repoRoot host ghcVersion = do
  let target = "toolchains//:haskell__archive_" <> platKey host
  out <-
    readProcessStdout_ . setWorkingDir repoRoot $
      proc "buck2" ["build", target, "--show-full-output"]
  archive <- case words (last (lines (BL.unpack out))) of
    [_, path] -> pure path
    _ -> fail ("unexpected `buck2 build --show-full-output` output for " <> target)
  -- The tarball wraps everything in one ghc-<version>-<platform> directory.
  listDirectory archive >>= \case
    [root] -> pure (archive </> root </> "bin" </> ("ghc-" <> prettyShow ghcVersion))
    entries -> fail ("expected one directory in " <> archive <> ", got " <> show entries)
